	public function foreignkey($table, $user){
		//$rsm = new ResultSetMapping();
$em=$this->getEntityManager();

		$sql = "Select TABLE_NAME,
    COLUMN_NAME,
    REFERENCED_TABLE_NAME
FROM
    INFORMATION_SCHEMA.KEY_COLUMN_USAGE
    WHERE
    REFERENCED_TABLE_NAME IN (?)
    AND REFERENCED_COLUMN_NAME = 'id'
    Order By REFERENCED_TABLE_NAME ASC
";
		$qb = $em->getConnection()->executeQuery($sql,[$table],[\Doctrine\DBAL\connection::PARAM_STR_ARRAY]);
		// $qb->bindValue($table);
		           //$qb->execute();

		$dependances = $qb->fetchAll();

		$tab=[];

		$tab['agent']=$user->getAgent();
		foreach ($dependances as $key => $dependance) {
			$from=$dependance["TABLE_NAME"];
			$colonne=$dependance["COLUMN_NAME"];
			$objet=$dependance["REFERENCED_TABLE_NAME"];
			if($objet=="users"){
				$id=$user->getId();
			}elseif($objet=="agent"){
				$id=$user->getAgent()->getId();
			}
			
			$sql="select * from {$from} where  {$colonne} = ?";
			//echo $sql."***".$id."<br>";
			$q = $em->getConnection()->executeQuery($sql,[$id]);
			
			$cte=[];
			$cte=$q->fetchAll();
			if(count($cte)>0){
				if(isset($tab[$from])){
					$tab['object'][$from]=array_merge($tab[$from],$cte);
				}else{
					$tab['object'][$from]=$cte;
				}
			
				$sql1="Set foreign_key_checks = 0; delete  from {$from} where  {$colonne} = ? ;";
			//echo $sql."***".$id."<br>";
			   $em->getConnection()->executeQuery($sql1,[$id]);

			}
			
		}

	$sql="select * from agent where  id = ?";
			$q = $em->getConnection()->executeQuery($sql,[$user->getAgent()->getId()]);

$tab['agt']=$q->fetchAll();
return $tab;
		//dump($tab);

	}

